package main

import (
	"cmp"
	"fmt"
	"slices"
	"strings"
)

type City struct {
	Name   string
	Region string
	Pop    int // population in thousands, approximate
}

func main() {
	nums := []int{42, 7, 19, 7, 3}
	fmt.Println(slices.Contains(nums, 19), slices.Index(nums, 7), slices.Max(nums))

	slices.Sort(nums) // in place, ascending
	pos, found := slices.BinarySearch(nums, 19)
	fmt.Println(nums, pos, found)

	cities := []City{
		{"İzmir", "Ege", 4479},
		{"Manisa", "Ege", 1475},
		{"Ankara", "İç Anadolu", 5864},
		{"Konya", "İç Anadolu", 2330},
		{"Aydın", "Ege", 1166},
	}
	// SortFunc takes a three-way comparison. cmp.Or returns the first
	// non-zero result: region ascending, then population descending.
	slices.SortFunc(cities, func(a, b City) int {
		return cmp.Or(
			strings.Compare(a.Region, b.Region),
			cmp.Compare(b.Pop, a.Pop),
		)
	})
	for _, c := range cities {
		fmt.Printf("%-11s %-7s %5d\n", c.Region, c.Name, c.Pop)
	}

	over5M := func(c City) bool { return c.Pop > 5000 }
	if i := slices.IndexFunc(cities, over5M); i >= 0 {
		fmt.Println("first city over 5M:", cities[i].Name)
	}

	// Sorting compares bytes, not the Turkish alphabet: Ç and İ land after Z.
	names := []string{"Zonguldak", "Çorum", "İzmir", "Ankara", "Iğdır"}
	slices.Sort(names)
	fmt.Println(names)
}

files.examples/02_edit_copy_clear.go:
package main

import (
	"fmt"
	"slices"
)

func main() {
	tags := []string{"go", "sql", "sql", "ts", "go"}

	// De-duplicate: sort, then Compact drops adjacent repeats.
	uniq := slices.Compact(slices.Sorted(slices.Values(tags)))
	fmt.Printf("%q\n", uniq)

	uniq = slices.Insert(uniq, 1, "react")
	fmt.Printf("%q\n", uniq)

	// Delete works in place and zeroes the slots it vacated (Go 1.22), so an
	// old header that still covers them sees "" instead of stale data.
	before := uniq
	uniq = slices.Delete(uniq, 0, 2)
	fmt.Printf("%q %q\n", uniq, before)

	// Filter in place instead of a loop that builds a second slice.
	nums := []int{1, 2, 3, 4, 5, 6}
	nums = slices.DeleteFunc(nums, func(n int) bool { return n%2 == 0 })
	fmt.Println(nums)

	// The copy built-in copies min(len(dst), len(src)) elements; it never grows dst.
	dst := make([]int, 2)
	n := copy(dst, []int{7, 8, 9})
	fmt.Println(n, dst)

	// Clone gives an independent copy; Equal compares element by element.
	c := slices.Clone(nums)
	c[0] = 100
	fmt.Println(slices.Equal(c, nums), nums, c)

	// clear (Go 1.21) zeroes a slice's elements but keeps its length.
	clear(c)
	fmt.Println(c, len(c))
}

files.examples/03_maps_pkg.go:
package main

import (
	"fmt"
	"maps"
	"slices"
	"strings"
)

func main() {
	defaults := map[string]string{"lang": "tr", "theme": "light", "tz": "Europe/Istanbul"}
	user := map[string]string{"theme": "dark"}

	// Merge: start from a copy of the defaults, then overwrite with the user's.
	settings := maps.Clone(defaults)
	maps.Copy(settings, user)
	fmt.Println(settings)
	fmt.Println("defaults untouched:", defaults["theme"])

	// Keys and Values return iterators (Go 1.23); collect them as needed.
	fmt.Println(slices.Sorted(maps.Keys(settings)))
	fmt.Println(slices.Sorted(maps.Values(settings)))

	// Remove entries matching a predicate without a hand-written loop.
	maps.DeleteFunc(settings, func(k, v string) bool {
		return strings.HasPrefix(v, "Europe/")
	})
	want := map[string]string{"lang": "tr", "theme": "dark"}
	fmt.Println(settings, maps.Equal(settings, want))

	// Build a map from any key/value iterator: here, index -> element.
	byIndex := maps.Collect(slices.All([]string{"sıfır", "bir", "iki"}))
	fmt.Println(byIndex)

	// clear deletes every entry; the map stays usable (unlike a nil map).
	clear(settings)
	settings["lang"] = "en"
	fmt.Println(settings, len(settings))
}
